===== Tripo3d_Blender_Bridge/core/auto_update.py =====
"""Plugin update policy, package transaction and Blender lifecycle.

Pure manifest/package operations are usable by release tools without Blender.
Host imports are limited to lifecycle entry points.
"""
from pathlib import Path, PurePosixPath
import ast
import hashlib
import json
import logging
import os
import queue
import re
import shutil
import stat
import tempfile
import threading
import time
import unicodedata
from urllib.parse import urlsplit
from urllib.request import Request, build_opener, HTTPRedirectHandler
import uuid
import zipfile

logger = logging.getLogger("tripo_addon")


# Manifest checks and channel policy
PLUGIN_ID = "blender-bridge"
CHANNEL = "intl"  # Replaced by pack-CN.py for the domestic package.
BASES = (
    "https://tripo-public.tripo3d.ai/plugins/blender-bridge/",
    "https://assets.cdn.tripo3d.com/fe-tripo-studio/plugins/blender-bridge/",
)
TIMEOUT = 4
MAX_BYTES = 65536
TTL = 24 * 60 * 60


def version(value):
    if not isinstance(value, str) or not re.fullmatch(r"[vV]?\d+[._]\d+[._]\d+", value):
        raise ValueError("invalid stable version")
    return tuple(int(p) for p in value.lstrip("vV").replace("_", ".").split("."))


def version_text(value):
    """Canonical dotted version. The parser accepts an optional v prefix; UI text does not."""
    return ".".join(map(str, version(value)))


def safe_url(value, local=False):
    if not isinstance(value, str) or any(c.isspace() for c in value):
        raise ValueError("invalid URL")
    parts = urlsplit(value)
    if parts.username or parts.password or not parts.hostname:
        raise ValueError("invalid URL")
    if parts.scheme != "https" and not (local and parts.scheme == "http" and parts.hostname == "127.0.0.1"):
        raise ValueError("HTTPS required")
    return value


class SafeRedirect(HTTPRedirectHandler):
    def __init__(self, local):
        self.local = local

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        safe_url(newurl, self.local)
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def clean_notes(value):
    if not isinstance(value, str):
        return ""
    return "".join(c for c in value[:2000] if c == "\n" or not unicodedata.category(c).startswith("C"))


def resolve(manifest, current):
    if not isinstance(manifest, dict) or manifest.get("schema_version") != 1 or manifest.get("id") != PLUGIN_ID:
        raise ValueError("invalid manifest identity/schema")
    latest = manifest["version"]
    latest_v, current_v = version(latest), version(current)
    package = manifest["packages"]["default"]
    local_test = urlsplit(os.environ.get("TRIPO_UPDATE_URL", "")).hostname == "127.0.0.1"
    url = safe_url(package["url"], local_test)
    digest = package.get("sha256", "")
    if not isinstance(digest, str) or not re.fullmatch(r"[0-9a-fA-F]{64}", digest):
        raise ValueError("invalid package SHA-256")
    result = {"available": latest_v > current_v, "current": current, "latest": version_text(latest),
              "url": url, "sha256": digest.lower(), "channel": manifest.get("channel"),
              "auto_install": manifest.get("channel") == CHANNEL,
              "notes": "", "feature_version": "", "release_url": ""}
    feature = manifest.get("feature_release")
    if result["available"] and isinstance(feature, dict):
        try:
            fv = version(feature.get("version"))
            if current_v[:2] < fv[:2] == latest_v[:2] and fv <= latest_v:
                result["notes"] = clean_notes(feature.get("notes"))
                result["feature_version"] = feature["version"]
                if feature.get("release_url"):
                    result["release_url"] = safe_url(feature["release_url"])
        except (ValueError, TypeError):
            # Bad optional notes must not hide an otherwise valid update.
            result.update(notes="", feature_version="", release_url="")
    return result


def sources():
    override = os.environ.get("TRIPO_UPDATE_URL")
    ordered = BASES if CHANNEL == "intl" else tuple(reversed(BASES))
    return [safe_url(override, True)] if override else [b + "manifest.json" for b in ordered]


def fetch(url, method="GET", local=False):
    safe_url(url, local)
    request = Request(url, method=method, headers={"User-Agent": "Tripo-Blender-Update/1"})
    with build_opener(SafeRedirect(local)).open(request, timeout=TIMEOUT) as response:
        if method == "HEAD":
            return response.headers.get("x-amz-meta-version") or response.headers.get("x-oss-meta-version")
        raw = response.read(MAX_BYTES + 1)
        if len(raw) > MAX_BYTES:
            raise ValueError("manifest too large")
        return json.loads(raw)


def check(current, cache_dir, urls=None, now=None, force=False):
    """Run on a worker; cache validated manifests, never derived UI state."""
    if os.environ.get("TRIPO_UPDATE_CHECK") == "0":
        return {"disabled": True}
    urls = sources() if urls is None else urls
    now = time.time() if now is None else now
    version(current)
    key = hashlib.sha256(json.dumps([PLUGIN_ID, current, urls]).encode()).hexdigest()
    cache = Path(cache_dir) / (key + ".json")

    def save(entry):
        temporary = None
        try:
            cache.parent.mkdir(parents=True, exist_ok=True)
            with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=cache.parent, delete=False) as handle:
                temporary = Path(handle.name)
                json.dump(dict(entry, time=now), handle)
            temporary.replace(cache)
        except OSError:
            pass  # Read-only cache must not suppress notifications.
        finally:
            if temporary:
                try:
                    temporary.unlink(missing_ok=True)
                except OSError:
                    pass

    def legacy(latest, url):
        return {"available": version(latest) > version(current), "current": current,
                "latest": version_text(latest), "url": safe_url(url), "notes": "", "feature_version": "", "release_url": ""}

    try:
        saved = json.loads(cache.read_text(encoding="utf-8"))
        if not force and 0 <= now - saved["time"] < TTL:
            if "manifest" in saved:
                result = resolve(saved["manifest"], current)
            elif "legacy" in saved:
                result = legacy(**saved["legacy"])
            else:
                result = {"error": str(saved["error"])[:200]}
            result["cached"] = True
            return result
    except (OSError, ValueError, KeyError, TypeError):
        pass
    errors = []
    for url in urls:
        try:
            manifest = fetch(url, local=bool(os.environ.get("TRIPO_UPDATE_URL")))
            result = resolve(manifest, current)
            save({"manifest": manifest})
            return result
        except Exception as exc:
            errors.append(type(exc).__name__)
    # Migration only: test overrides must never leak requests to production.
    if not os.environ.get("TRIPO_UPDATE_URL") and set(urls) == {b + "manifest.json" for b in BASES}:
        for base in (BASES if CHANNEL == "intl" else tuple(reversed(BASES))):
            try:
                url = base + "Tripo3d_Blender_Bridge-latest.zip"
                latest = fetch(url, "HEAD")
                result = legacy(latest, url)
                save({"legacy": {"latest": latest, "url": url}})
                return result
            except Exception as exc:
                errors.append(type(exc).__name__)
    error = "all update sources failed: " + ", ".join(errors)
    save({"error": error})
    return {"error": error}


# Package validation and recoverable installation
PACKAGE = "Tripo3d_Blender_Bridge"
MAX_DOWNLOAD = 128 * 1024 * 1024
MAX_EXPANDED = 512 * 1024 * 1024
BACKUPS_TO_KEEP = 2


class Cancelled(Exception):
    pass


def ensure_running(cancel):
    if cancel.is_set():
        raise Cancelled("Update cancelled")


def archive_info(archive, expected, blender_version):
    """Inspect all names before writing any archive entries; never execute code."""
    with zipfile.ZipFile(archive) as package:
        members = package.infolist()
        if len(members) > 5000 or sum(m.file_size for m in members) > MAX_EXPANDED:
            raise ValueError("Package exceeds extraction limits")
        seen = set()
        for member in members:
            name = member.filename
            path = PurePosixPath(name)
            parts = name.rstrip('/').split('/')
            if (not parts or parts[0] != PACKAGE or path.is_absolute() or '\\' in name
                    or any(p in ('', '.', '..') or ':' in p or p.endswith((' ', '.'))
                           or re.fullmatch(r'(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\..*)?', p, re.I)
                           for p in parts)
                    or stat.S_ISLNK(member.external_attr >> 16) or member.flag_bits & 1):
                raise ValueError("Unsafe ZIP entry")
            key = name.rstrip('/').casefold()
            if key in seen:
                raise ValueError("Duplicate ZIP entry")
            seen.add(key)
        # Accept both the current feature layout and previously released packages.
        current_layout = PACKAGE + '/core/logger.py' in package.namelist()
        channel_file = 'core/auto_update.py' if current_layout else 'utils/update_check.py'
        logger_file = 'core/logger.py' if current_layout else 'utils/logger.py'
        required = ["__init__.py", "core/task.py", "ui/sidebar_panel.py", logger_file, channel_file]
        for name in required:
            if PACKAGE + '/' + name not in package.namelist():
                raise ValueError("Not a complete Tripo Bridge package")
        source = package.read(PACKAGE + '/__init__.py').decode('utf-8-sig')
        metadata = None
        for node in ast.parse(source).body:
            if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'bl_info' for t in node.targets):
                metadata = ast.literal_eval(node.value)
                break
        if not isinstance(metadata, dict) or metadata.get('name') != 'Tripo Bridge':
            raise ValueError("Unexpected plugin identity")
        if tuple(metadata.get('version', ())) != version(expected):
            raise ValueError("Package version does not match manifest")
        minimum = metadata.get('blender')
        if not isinstance(minimum, tuple) or len(minimum) != 3 or not all(type(n) is int for n in minimum):
            raise ValueError("Invalid Blender compatibility declaration")
        if tuple(blender_version) < minimum:
            raise ValueError("Package requires Blender " + '.'.join(map(str, minimum)))
        channel_source = package.read(PACKAGE + '/' + channel_file).decode('utf-8-sig')
        channels = [ast.literal_eval(node.value) for node in ast.parse(channel_source).body
                    if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == 'CHANNEL' for t in node.targets)]
        if channels != [CHANNEL]:
            raise ValueError("Package distribution channel does not match installed plugin")
        legacy_marker = PACKAGE + '/utils/update_check.py'
        if current_layout and legacy_marker in package.namelist():
            legacy_tree = ast.parse(package.read(legacy_marker).decode('utf-8-sig'))
            legacy_channels = [ast.literal_eval(node.value) for node in legacy_tree.body
                               if isinstance(node, ast.Assign) and any(
                                   isinstance(t, ast.Name) and t.id == 'CHANNEL' for t in node.targets)]
            if legacy_channels != channels:
                raise ValueError("Legacy channel marker does not match update implementation")
        return members


def cleanup(stage):
    """Only delete the unique staging directory returned by prepare()."""
    root, target = Path(stage['root']).resolve(), Path(stage['target']).resolve()
    if root.parent != target.parent or not root.name.startswith('.tripo-stage-') or root == target:
        raise ValueError("Invalid staging cleanup path")
    if root.exists():
        shutil.rmtree(root)


def prepare(update, target, blender_version, cancel, progress=lambda done, total: None):
    target = Path(target).resolve()
    if target.name != PACKAGE or not (target / '__init__.py').is_file():
        raise ValueError("Installed Tripo Bridge directory not found")
    if update.get('channel') != CHANNEL or not update.get('auto_install'):
        raise ValueError("Update channel is not verified for automatic installation")
    if version(update['latest']) <= version(update['current']):
        raise ValueError("Update must be newer than the running plugin")
    digest = update.get('sha256', '')
    if not re.fullmatch(r'[0-9a-f]{64}', digest):
        raise ValueError("Missing package SHA-256")
    local = urlsplit(os.environ.get('TRIPO_UPDATE_URL', '')).hostname == '127.0.0.1'
    url = safe_url(update['url'], local)
    parsed = urlsplit(url)
    allowed = {'tripo-public.tripo3d.ai', 'tripo-public.tripo3d.com', 'assets.cdn.tripo3d.com', 'tripo-cn-files.tripo3d.com'}
    if parsed.hostname not in allowed and not (local and parsed.hostname == '127.0.0.1'):
        raise ValueError("Package must be hosted by the Tripo release CDN")
    if not parsed.path.lower().endswith('.zip'):
        raise ValueError("Update package must be a ZIP")
    root = Path(tempfile.mkdtemp(prefix='.tripo-stage-', dir=target.parent))
    stage = {'root': str(root), 'target': str(target), 'version': update['latest']}
    try:
        archive = root / 'download.zip'
        checksum = hashlib.sha256()
        start = time.monotonic()
        request = Request(url, headers={'User-Agent': 'Tripo-Blender-Update/1'})
        with build_opener(SafeRedirect(local)).open(request, timeout=10) as response, archive.open('wb') as output:
            total = int(response.headers.get('Content-Length', 0))
            if total > MAX_DOWNLOAD:
                raise ValueError("Download is too large")
            count = 0
            while True:
                ensure_running(cancel)
                if time.monotonic() - start > 180:
                    raise TimeoutError("Download deadline exceeded")
                data = response.read(65536)
                if not data:
                    break
                count += len(data)
                if count > MAX_DOWNLOAD:
                    raise ValueError("Download is too large")
                output.write(data)
                checksum.update(data)
                progress(count, total)
        if checksum.hexdigest() != digest:
            raise ValueError("Package SHA-256 verification failed")
        members = archive_info(archive, update['latest'], blender_version)
        with zipfile.ZipFile(archive) as package:
            for member in members:
                ensure_running(cancel)
                destination = root / member.filename
                if member.is_dir():
                    destination.mkdir(parents=True, exist_ok=True)
                else:
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    with package.open(member) as source, destination.open('wb') as output:
                        shutil.copyfileobj(source, output)
        ensure_running(cancel)
        return stage
    except BaseException:
        cleanup(stage)
        raise


def prune_backups(target, keep=BACKUPS_TO_KEEP, protect=None):
    """Prune only completed, self-owned backups; keep recovery evidence intact."""
    target=Path(target).resolve()
    root=target.parent/'.tripo-update-backups'
    if not root.is_dir() or root.is_symlink() or root.resolve()!=root or root.resolve().parent!=target.parent:
        return
    candidates=[]
    for directory in root.iterdir():
        if not re.fullmatch(r'[0-9a-f]{32}',directory.name) or directory.is_symlink():continue
        try:
            if directory.resolve()!=directory or directory.resolve().parent!=root.resolve():continue
            backup=directory/PACKAGE
            if not backup.is_dir() or backup.resolve().parent!=directory.resolve():continue
            receipt=json.loads((directory/'receipt.json').read_text(encoding='utf8'))
            if not isinstance(receipt,dict):continue
            if receipt.get('state')!='installed' or Path(receipt.get('target','')).resolve()!=target:continue
            candidates.append(directory)
        except (OSError,ValueError,TypeError):
            continue
    candidates.sort(key=lambda path:path.stat().st_mtime_ns,reverse=True)
    retained={Path(protect).resolve()} if protect is not None else set()
    for directory in candidates:
        if len(retained)<max(1,keep):retained.add(directory.resolve())
        if directory.resolve() in retained:continue
        # Revalidate the resolved deletion target immediately before rmtree.
        if directory.resolve().parent==root.resolve() and not directory.is_symlink():
            shutil.rmtree(directory)


def commit(stage):
    """Call only after host has stopped bridge workers; retain backup on success."""
    target = Path(stage['target']).resolve()
    root = Path(stage['root']).resolve()
    if root.parent != target.parent or not root.name.startswith('.tripo-stage-'):
        raise ValueError("Invalid stage location")
    incoming = root / PACKAGE
    if target.name != PACKAGE or not (incoming / '__init__.py').is_file() or not target.is_dir():
        raise ValueError("Invalid staged installation")
    backup_dir = target.parent / '.tripo-update-backups' / uuid.uuid4().hex
    backup_dir.mkdir(parents=True)
    backup = backup_dir / PACKAGE
    receipt = backup_dir / 'receipt.json'
    receipt.write_text(json.dumps({'target': str(target), 'version': stage['version'], 'state': 'prepared'}), encoding='utf-8')
    os.replace(target, backup)
    try:
        os.replace(incoming, target)
    except BaseException as install_error:
        try:
            os.replace(backup, target)
        except BaseException as restore_error:
            raise RuntimeError(f"Installation and rollback failed. Backup: {backup}; {restore_error}") from install_error
        raise
    # Installation is already complete: receipt/temporary cleanup failure must
    # never be presented as installation failure or restart the old service.
    try:
        receipt.write_text(json.dumps({'target': str(target), 'version': stage['version'], 'state': 'installed'}), encoding='utf-8')
        cleanup(stage)
        prune_backups(target,protect=backup_dir)
    except OSError:
        pass
    return str(backup)


# Blender lifecycle and user actions
state = {}
_cancel = None
_poll = None
_messages = None
_handoff = threading.Lock()
_release_resources = None


def configure_resources(release):
    """Plugin entry point supplies its main-thread resource-release callback."""
    global _release_resources
    _release_resources = release



def redraw():
    import bpy
    for window in bpy.context.window_manager.windows:
        for area in window.screen.areas:
            if area.type == 'VIEW_3D':
                area.tag_redraw()


def install_target():
    import bpy
    target = Path(__file__).resolve().parents[1]
    expected = Path(bpy.utils.user_resource('SCRIPTS', path='addons')) / PACKAGE
    if target != expected.resolve():
        raise ValueError("Install the add-on in Blender's user add-ons directory first")
    return target


def require_idle():
    from . import task
    from .status_manager import status, ConnectionState
    manager = task.task_manager
    server = manager.ws_server if manager else None
    if status.state == ConnectionState.CONNECTED or (server and (
            server.has_connections() or server.has_pending_imports())):
        raise ValueError("Disconnect Tripo Studio and finish pending imports before updating")


def start():
    import bpy
    global _cancel, _poll, _messages
    from .. import bl_info
    if state.get('phase') in ('downloading', 'installed'):
        return False
    try:
        target = install_target()
        require_idle()
    except Exception as exc:
        state.update(phase='failed', error=str(exc))
        logger.warning('[TripoUpdate] install cannot start: %s', exc)
        redraw()
        return False
    current = '.'.join(map(str, bl_info['version']))
    host_version = tuple(bpy.app.version)
    cache = bpy.utils.user_resource('CONFIG', path='tripo-update', create=True)
    cancel = threading.Event()
    messages = queue.Queue()
    _cancel, _messages = cancel, messages
    state.clear()
    state.update(phase='downloading', progress=0.0)

    def progress(done, total):
        # Keep only the newest progress value, not one queued event per chunk.
        with _handoff:
            if not cancel.is_set():
                progress.value = done / total if total else 0.0
    progress.value = 0.0

    def worker():
        stage = None
        try:
            update = check(current, cache, force=True)
            if not update.get('available'):
                raise ValueError(update.get('error', 'No newer release is available'))
            stage = prepare(update, target, host_version, cancel, progress)
            with _handoff:
                if not cancel.is_set():
                    messages.put(('ready', (stage, update)))
                    stage = None  # Timer now owns cleanup.
        except Exception as exc:
            if not cancel.is_set():
                messages.put(('error', str(exc)))
        finally:
            if stage:
                cleanup(stage)

    def poll():
        if cancel.is_set():
            return None
        state['progress'] = progress.value
        redraw()
        try:
            kind, payload = messages.get_nowait()
        except queue.Empty:
            return .2
        if kind == 'error':
            state.update(phase='failed', error=payload)
            logger.warning('[TripoUpdate] install failed: %s', payload)
            return None
        stage, update = payload
        notice.update(update)
        stopped = False
        manager = None
        try:
            # Recheck after download: a browser may have connected meanwhile.
            require_idle()
            from . import task
            manager = task.task_manager
            if manager:
                if not manager.stop():
                    raise RuntimeError('Bridge has not stopped; restart Blender before updating')
                stopped = True
            # BLF keeps font files open without Windows delete sharing. Stop
            # holding our assets before renaming the plugin directory; no UI
            # redraw runs between this release and the synchronous swap.
            if _release_resources is None:
                raise RuntimeError('Update resource lifecycle is not configured')
            _release_resources()
            backup = commit(stage)
            state.update(phase='installed', latest=update['latest'], backup=backup, progress=1.0)
            logger.warning('[TripoUpdate] installed version=%s backup=%s; restart Blender', update['latest'], backup)
            # Do not reload Python modules or restart the bridge in this process.
        except Exception as exc:
            state.update(phase='failed', error=str(exc))
            logger.warning('[TripoUpdate] install failed: %s', exc)
            if stopped and manager and Path(stage['target']).is_dir():
                manager.start()
            try:
                cleanup(stage)
            except OSError:
                pass
        redraw()
        return None

    _poll = poll
    bpy.app.timers.register(poll, first_interval=.2, persistent=True)
    threading.Thread(target=worker, name='TripoUpdateInstall', daemon=True).start()
    return True


def unregister():
    import bpy
    global _cancel, _poll, _messages
    _cancel_check()
    with _handoff:
        if _cancel:
            _cancel.set()
        if _messages:
            while not _messages.empty():
                kind, payload = _messages.get_nowait()
                if kind == 'ready':
                    try:
                        cleanup(payload[0])
                    except OSError as exc:
                        # Locked temporary files must not prevent Blender from
                        # unregistering the add-on and its UI/timers.
                        logger.warning('[TripoUpdate] staging cleanup failed: %s', exc)
    if _poll and bpy.app.timers.is_registered(_poll):
        bpy.app.timers.unregister(_poll)
    _cancel = _poll = _messages = None
    state.clear()


notice = {}
status = {"checking": False, "checked": False, "manual": False}
_check_stop = None
_check_timer = None


def request_check():
    """Refresh on explicit click without downloading or installing a package."""
    if status["checking"] or state.get("phase") in ("downloading", "installed"):
        return False
    _start_check(force=True, delay=0.0)
    return True


def register():
    _start_check(force=False, delay=5.0)


def _start_check(force, delay):
    import bpy
    global _check_stop, _check_timer
    _cancel_check()
    if os.environ.get("TRIPO_UPDATE_CHECK") == "0":
        status.update(checking=False, checked=True, disabled=True)
        return
    status.update(checking=True, checked=False, disabled=False, manual=force)
    from .. import bl_info
    current = ".".join(map(str, bl_info["version"]))
    cache_dir = bpy.utils.user_resource('CONFIG', path="tripo-update", create=True)
    stopped = threading.Event()
    results = queue.Queue()
    _check_stop = stopped
    started = False

    def worker():
        try:
            result = check(current, cache_dir, force=force)
        except Exception as exc:
            result = {"error": str(exc)}
        if not stopped.is_set():
            results.put(result)

    def poll():
        nonlocal started
        if stopped.is_set():
            return None
        if not started:
            started = True
            threading.Thread(target=worker, name="TripoUpdate", daemon=True).start()
        try:
            result = results.get_nowait()
        except queue.Empty:
            return 0.2
        notice.clear()
        notice.update(result)
        status.update(checking=False, checked=True)
        if result.get("available"):
            logger.info("New version %s is available. Current version: %s.",
                        result["latest"], current)
        elif result.get("error"):
            logger.info("Could not check for updates: %s", result["error"])
        elif not result.get("disabled"):
            logger.info("The plugin is on the latest version.")
        redraw()
        return None

    _check_timer = poll
    bpy.app.timers.register(poll, first_interval=delay, persistent=True)


def _cancel_check():
    import bpy
    global _check_stop, _check_timer
    if _check_stop:
        _check_stop.set()
    if _check_timer and bpy.app.timers.is_registered(_check_timer):
        bpy.app.timers.unregister(_check_timer)
