"""Read a native panel's position without assuming a Blender ABI layout.

Panel offsets are not exposed through RNA. Blender changes these offsets while
dragging a header, independently of View2D scrolling. Discover the field offsets
from the running binary's embedded SDNA, then read only a live Panel's geometry.
No Blender memory is written and no version-specific C offsets are hard-coded.
"""
import ctypes
from dataclasses import dataclass
from functools import lru_cache
import mmap
from pathlib import Path
import re
import struct
import sys


class SchemaError(ValueError):
    pass


@dataclass(frozen=True)
class PanelGeometry:
    x: int
    y: int
    width: int
    height: int

    @property
    def top(self):
        return self.y + self.height


@dataclass(frozen=True)
class PanelLayout:
    size: int
    name_offset: int
    name_size: int
    offsets: tuple
    byteorder: str

    def read(self, panel):
        """Copy geometry during a live Panel draw callback only.

        A matching name cannot make a stale pointer safe. Callers must not keep
        an RNA Panel for later rendering/events; retain this immutable result.
        """
        try:
            pointer = panel.as_pointer()
            identifier = panel.bl_idname.encode('utf8')
        except (AttributeError, ReferenceError):
            return None
        if not pointer or not identifier or len(identifier) >= self.name_size:
            return None
        # Blender owns the Panel for the duration of the native draw callback.
        data = ctypes.string_at(pointer, self.size)
        name = data[self.name_offset:self.name_offset+self.name_size].split(b'\0', 1)[0]
        if name != identifier:
            return None
        values = tuple(struct.unpack_from(self.byteorder+'i', data, offset)[0]
                       for offset in self.offsets)
        x, y, width, height = values
        if not (0 < width < 100000 and 0 < height < 1000000
                and abs(x) < 1000000 and abs(y) < 10000000):
            return None
        return PanelGeometry(*values)


def parse_panel_layout(data, pointer_size, byteorder):
    """Parse Blender's SDNA tables, including explicit ABI padding fields."""
    if pointer_size not in (4, 8) or byteorder not in ('<', '>'):
        raise SchemaError('Unsupported pointer size or byte order')
    position = 0

    def tag(expected):
        nonlocal position
        if data[position:position+len(expected)] != expected:
            raise SchemaError('Missing SDNA tag '+expected.decode())
        position += len(expected)

    def number(fmt):
        nonlocal position
        size = struct.calcsize(fmt)
        if position+size > len(data):
            raise SchemaError('Truncated SDNA table')
        value = struct.unpack_from(byteorder+fmt, data, position)[0]
        position += size
        return value

    def align():
        nonlocal position
        position = (position+3) & ~3

    def strings():
        nonlocal position
        count = number('I')
        if not 0 < count <= 500000:
            raise SchemaError('Invalid SDNA string count')
        result = []
        for _ in range(count):
            end = data.find(b'\0', position)
            if end < 0:
                raise SchemaError('Unterminated SDNA string')
            result.append(data[position:end].decode('ascii'))
            position = end+1
        align()
        return result

    tag(b'SDNANAME')
    names = strings()
    tag(b'TYPE')
    types = strings()
    tag(b'TLEN')
    lengths = [number('H') for _ in types]
    align()
    tag(b'STRC')
    count = number('I')
    if count > len(types):
        raise SchemaError('Invalid SDNA structure count')
    for _ in range(count):
        type_index, field_count = number('H'), number('H')
        if type_index >= len(types) or field_count > len(names):
            raise SchemaError('Invalid SDNA structure')
        fields = [(number('H'), number('H')) for _ in range(field_count)]
        if types[type_index] != 'Panel':
            continue
        offset = 0
        found = {}
        for field_type, field_name in fields:
            if field_type >= len(types) or field_name >= len(names):
                raise SchemaError('Invalid SDNA field index')
            name = names[field_name]
            base = re.search(r'[A-Za-z_]\w*', name)
            if base is None:
                raise SchemaError('Invalid SDNA field name')
            size = pointer_size if '*' in name else lengths[field_type]
            for dimension in re.findall(r'\[(\d+)\]', name):
                size *= int(dimension)
            found[base[0]] = (offset, size, types[field_type])
            offset += size
        if offset != lengths[type_index] or not 64 <= offset <= 8192:
            raise SchemaError('Panel SDNA does not match its ABI size')
        required = ('ofsx', 'ofsy', 'sizex', 'sizey')
        if any(name not in found or found[name][1:] != (4, 'int') for name in required):
            raise SchemaError('Panel geometry fields are unavailable')
        name_field = found.get('panelname')
        if not name_field or name_field[2] != 'char' or not 32 <= name_field[1] <= 256:
            raise SchemaError('Panel identity field is unavailable')
        return PanelLayout(offset, name_field[0], name_field[1],
                           tuple(found[name][0] for name in required), byteorder)
    raise SchemaError('Panel was not found in SDNA')


@lru_cache(maxsize=4)
def layout_from_binary(binary_path):
    """Read only the local Blender executable; no subprocess or network calls."""
    byteorder = '<' if sys.byteorder == 'little' else '>'
    with Path(binary_path).open('rb') as source:
        with mmap.mmap(source.fileno(), 0, access=mmap.ACCESS_READ) as binary:
            offset = binary.find(b'SDNANAME')
            while offset >= 0:
                try:
                    return parse_panel_layout(binary[offset:offset+16*1024*1024],
                                              ctypes.sizeof(ctypes.c_void_p), byteorder)
                except (SchemaError, UnicodeDecodeError, struct.error):
                    offset = binary.find(b'SDNANAME', offset+8)
    raise SchemaError('The Blender executable contains no supported Panel SDNA')


def panel_displacement(geometry, anchor, view2d):
    """Translate the panel movement into the exact same View2D pixel space."""
    current = view2d.view_to_region(geometry.x, geometry.top, clip=False)
    original = view2d.view_to_region(anchor[0], anchor[1], clip=False)
    return current[0]-original[0], current[1]-original[1]


